                { id: "q_exp_3_2", question: "Kompleksitas waktu pencarian di BST yang seimbang (balanced)?", options: ["O(log n) — setiap langkah memotong setengah ruang pencarian", "O(n)", "O(1)", "O(n^2)"], correctIndex: 0 },
                { id: "q_exp_3_3", question: "BFS (Breadth-First Search) menggunakan struktur data apa?", options: ["Queue — memproses node level per level (yang lebih dekat dulu)", "Stack", "Linked List", "Array sorted"], correctIndex: 0 },
                { id: "q_exp_3_4", question: "DFS (Depth-First Search) menggunakan struktur data apa?", options: ["Stack (atau rekursi) — menyelam sedalam mungkin sebelum backtrack", "Queue", "Hash Table", "Heap"], correctIndex: 0 },
                { id: "q_exp_3_5", question: "Keunggulan Hash Table (dictionary/object) dibanding Array untuk pencarian berdasarkan key?", options: ["Pencarian O(1) average — langsung melompat ke lokasi data via fungsi hash, tanpa iterasi", "Hash Table selalu lebih cepat untuk semua operasi", "Hash Table menggunakan memori lebih sedikit", "Hash Table bisa diurutkan lebih cepat"], correctIndex: 0 },
                { id: "q_exp_3_6", question: "Hash Collision terjadi ketika?", options: ["Dua key yang berbeda menghasilkan nilai hash yang sama, sehingga merujuk ke lokasi memori yang sama", "Hash table penuh 100%", "Key bernilai null", "Fungsi hash terlalu cepat"], correctIndex: 0 },
                { id: "q_exp_3_7", question: "In-order traversal pada BST menghasilkan?", options: ["Data dalam urutan terurut (ascending) — karena pola: left, root, right", "Data dalam urutan terbalik", "Data acak", "Hanya node root"], correctIndex: 0 },
                { id: "q_exp_3_8", question: "Graph Adjacency List merepresentasikan graf dengan cara?", options: ["Dictionary/Map di mana setiap node menjadi key, dan value-nya adalah list node tetangganya", "Matriks 2D berisi 0 dan 1", "Array tunggal berisi semua edge", "Linked list tunggal"], correctIndex: 0 },
                { id: "q_exp_3_9", question: "Contoh penggunaan Graph di dunia nyata?", options: ["Google Maps (jalan), jejaring sosial (pertemanan), internet (routing), rekomendasi produk", "Hanya untuk visualisasi data", "Kalkulator", "Notepad"], correctIndex: 0 }
